(758, 'alice-07', 12, 'She sees only tea.', false),
(759, 'alice-07', 13, '“I don''t see any wine,” she says.', false),
(760, 'alice-07', 14, '“There isn''t any,” says the March Hare.', false),
(761, 'alice-07', 15, '“That is not very nice,” says Alice.', false),
(762, 'alice-07', 16, '“Your hair is too long,” says the Hatter.', false),
(763, 'alice-07', 17, '“Don''t say that! It is very rude,” says Alice.', false),
(764, 'alice-07', 18, 'Then the Hatter asks a riddle.', true),
(765, 'alice-07', 19, '“Why is a raven like a writing-desk?”', false),
(766, 'alice-07', 20, '“I like riddles!” says Alice.', false),
(767, 'alice-07', 21, '“I can answer that.”', false),
(768, 'alice-07', 22, 'Then the Hatter takes out his watch.', false),
(769, 'alice-07', 23, 'He looks at it and shakes it.', false),
(770, 'alice-07', 24, 'There is butter in his watch!', false),
(771, 'alice-07', 25, 'The March Hare puts it in his cup of tea.', false),
(772, 'alice-07', 26, '“What is the answer to the riddle?” asks Alice.', false),
(773, 'alice-07', 27, '“I don''t know,” say the Hatter and the March Hare.', false),
(774, 'alice-07', 28, 'Alice is angry.', false),
(775, 'alice-07', 29, '“Why ask riddles with no answers?”', false),
(776, 'alice-07', 30, '“What time is it?” asks Alice.', true),
(777, 'alice-07', 31, '“It is always six o''clock here,” says the Hatter.', false),
(778, 'alice-07', 32, '“Time is angry with me.”', false),
(779, 'alice-07', 33, '“So it is always tea-time.”', false),
(780, 'alice-07', 34, '“We have no time to wash the cups.”', false),
(781, 'alice-07', 35, '“So we move round the table to clean cups.”', false),
(782, 'alice-07', 36, 'Then the Dormouse wakes up and tells a story.', true),
(783, 'alice-07', 37, 'It is a story about three sisters in a well.', false),
(784, 'alice-07', 38, 'But it is very strange, and he falls asleep again.', false),
(785, 'alice-07', 39, 'The Hatter and the March Hare are rude to Alice.', false),
(786, 'alice-07', 40, '“I don''t like this tea-party,” she says.', false),
(787, 'alice-07', 41, 'She gets up and walks away.', false),
(788, 'alice-07', 42, 'Then she looks back.', false),
(789, 'alice-07', 43, 'They are trying to put the Dormouse in the teapot!', false),
(790, 'alice-07', 44, 'In the wood, Alice sees a tree with a door in it.', true),
(791, 'alice-07', 45, 'She opens the door and goes in.', false),
(792, 'alice-07', 46, 'She is in the long hall again!', false),
(793, 'alice-07', 47, 'She takes the little gold key and opens the small door.', false),
(794, 'alice-07', 48, 'Then she eats a little of the mushroom and becomes small.', false),
(795, 'alice-07', 49, 'At last, she walks into the beautiful garden!', false),
(796, 'alice-08', 1, 'The garden is very beautiful.', true),
(797, 'alice-08', 2, 'Near the door, there is a big rose tree.', false),
(798, 'alice-08', 3, 'Its roses are white.', false),
(799, 'alice-08', 4, 'Three gardeners are painting the roses red.', false),
(800, 'alice-08', 5, 'They are big, flat cards with arms and legs!', false),
(801, 'alice-08', 6, '“Why do you paint the roses?” asks Alice.', false),
(802, 'alice-08', 7, '“This tree must be red, not white,” says one gardener.', false),
(803, 'alice-08', 8, '“The Queen wants red roses.”', false),
(804, 'alice-08', 9, '“When she sees white roses, she cuts off our heads!”', false),
(805, 'alice-08', 10, 'Then they hear a noise.', true),
(806, 'alice-08', 11, '“The Queen! The Queen!”', false),
(807, 'alice-08', 12, 'The gardeners lie down on their faces.', false),
(808, 'alice-08', 13, 'Many soldiers come into the garden.', false),
(809, 'alice-08', 14, 'They are cards too.', false),
(810, 'alice-08', 15, 'The White Rabbit comes too.', false),
(811, 'alice-08', 16, 'Last come the King and the Queen of Hearts.', false),
(812, 'alice-08', 17, 'The Queen sees Alice.', true),
(813, 'alice-08', 18, '“Who is this?” she asks angrily.', false),
(814, 'alice-08', 19, '“My name is Alice, Your Majesty,” says Alice.', false),
(815, 'alice-08', 20, 'Then the Queen looks at the rose tree and the gardeners.', false),
(816, 'alice-08', 21, 'Her face becomes red.', false),
(817, 'alice-08', 22, '“Off with their heads!” she shouts.', false),
(818, 'alice-08', 23, 'But Alice hides the gardeners in a big flowerpot.', false),
(819, 'alice-08', 24, 'The soldiers cannot find them.', false),
(820, 'alice-08', 25, '“Can you play croquet?” the Queen asks Alice.', true),
(821, 'alice-08', 26, '“Yes!” says Alice.', false),
(822, 'alice-08', 27, '“Then come with me!”', false),
(823, 'alice-08', 28, 'It is a very strange game.', false),
(824, 'alice-08', 29, 'The balls are hedgehogs.', false),
(825, 'alice-08', 30, 'The players hit the balls with flamingos.', false),
(826, 'alice-08', 31, 'The soldiers bend down and make little doors for the balls.', false),
(827, 'alice-08', 32, 'Alice''s flamingo does not stay still.', false),
(828, 'alice-08', 33, 'It turns its long neck and looks at her face.', false),
(829, 'alice-08', 34, 'Her hedgehog walks away.', false),
(830, 'alice-08', 35, 'Everybody plays at the same time, and everybody shouts.', false),
(831, 'alice-08', 36, 'The Queen is very angry.', false),
(832, 'alice-08', 37, 'Every minute she shouts, “Off with his head!” or “Off with her head!”', false),
(833, 'alice-08', 38, 'Alice is afraid.', false),
(834, 'alice-08', 39, '“What about my head?” she thinks.', false),
(835, 'alice-08', 40, 'Then Alice sees a big grin in the air.', true),
(836, 'alice-08', 41, 'It is the Cheshire Cat!', false),
(837, 'alice-08', 42, 'Slowly, its head appears, but not its body.', false),
(838, 'alice-08', 43, '“How are you?” asks the Cat.', false),
(839, 'alice-08', 44, '“Not very well,” says Alice.', false),
(840, 'alice-08', 45, '“This game has no rules.”', false),
(841, 'alice-08', 46, 'The King sees the Cat''s head.', false),
(842, 'alice-08', 47, '“I don''t like that cat,” he says.', false),
(843, 'alice-08', 48, '“Off with its head!” says the Queen.', false),
(844, 'alice-08', 49, 'But how can you cut off a head with no body?', false),
(845, 'alice-08', 50, 'Everybody talks about it, and the Cat smiles.', false),
(846, 'alice-08', 51, 'Then, slowly, the head disappears.', false),
(847, 'alice-09', 1, 'Then the Duchess comes to Alice.', true),
(848, 'alice-09', 2, 'She is very happy to see her.', false),
(849, 'alice-09', 3, 'She walks with Alice, arm in arm.', false),
(850, 'alice-09', 4, 'She is very friendly now.', false),
(851, 'alice-09', 5, '“There is no pepper here,” Alice thinks.', false),
(852, 'alice-09', 6, '“Maybe pepper makes people angry.”', false),
(853, 'alice-09', 7, 'But the Queen comes, and the Duchess runs away.', false),
(854, 'alice-09', 8, '“Do you know the Mock Turtle?” the Queen asks Alice.', true),
(855, 'alice-09', 9, '“No. What is a Mock Turtle?” says Alice.', false),
(856, 'alice-09', 10, '“The Gryphon can take you to him,” says the Queen.', false),
(857, 'alice-09', 11, 'A Gryphon is asleep in the sun.', false),
(858, 'alice-09', 12, 'It has the head of a bird and the body of a lion.', false),
(859, 'alice-09', 13, 'The Gryphon wakes up and takes Alice to the sea.', false),
(860, 'alice-09', 14, 'The Mock Turtle sits alone on a rock.', true),
(861, 'alice-09', 15, 'He is very sad.', false),
(862, 'alice-09', 16, 'Tears run down his face.', false),
(863, 'alice-09', 17, '“Why is he sad?” asks Alice.', false),
(864, 'alice-09', 18, '“Oh, he is not really sad,” says the Gryphon.', false),
(865, 'alice-09', 19, 'The Mock Turtle looks at Alice with big eyes.', false),
(866, 'alice-09', 20, '“I am not a real turtle,” he says sadly.', false),
(867, 'alice-09', 21, 'Then he talks about his school.', true),
(868, 'alice-09', 22, '“Our school is in the sea,” he says.', false),
(869, 'alice-09', 23, '“Our teacher is an old turtle.”', false),
(870, 'alice-09', 24, '“We have very strange lessons.”', false),
(871, 'alice-09', 25, '“We learn Reeling and Writhing, not Reading and Writing.”', false),
(872, 'alice-09', 26, '“How many hours of lessons do you have?” asks Alice.', false),
(873, 'alice-09', 27, '“Ten hours on the first day, nine on the next, and so on.”', false),
(874, 'alice-09', 28, '“They become less every day. That''s why they are lessons!”', false),
(875, 'alice-09', 29, '“Now let''s dance the Lobster Quadrille!” says the Gryphon.', true),
(876, 'alice-09', 30, '“What is that?” asks Alice.', false),
(877, 'alice-09', 31, '“It is a dance with lobsters,” says the Mock Turtle.', false),
(878, 'alice-09', 32, '“You stand in a line by the sea.”', false),
(879, 'alice-09', 33, '“Then you throw the lobsters into the water!”', false),
(880, 'alice-09', 34, '“And you swim after them!”', false),
(881, 'alice-09', 35, 'The Gryphon and the Mock Turtle dance around Alice.', false),
(882, 'alice-09', 36, 'The Mock Turtle sings a slow, sad song.', false),
(883, 'alice-09', 37, '“Thank you. It is a very nice dance,” says Alice.', false),
(884, 'alice-09', 38, 'Then they hear a cry from far away: “The trial is starting!”', false),
(885, 'alice-09', 39, '“Come on!” says the Gryphon, and he runs with Alice.', false),
(886, 'alice-10', 1, 'Alice and the Gryphon come to a big room.', true),
(887, 'alice-10', 2, 'It is a court.', false),
(888, 'alice-10', 3, 'The King and Queen of Hearts sit on two big chairs.', false),
(889, 'alice-10', 4, 'Many animals and birds are in the room.', false),
(890, 'alice-10', 5, 'In the middle, there is a table with a plate of tarts.', false),
(891, 'alice-10', 6, 'They look very good, and Alice is hungry.', false),
(892, 'alice-10', 7, 'The Knave of Hearts stands in front of the King.', true),
(893, 'alice-10', 8, 'Soldiers stand near him.', false),
(894, 'alice-10', 9, 'The King is the judge.', false),
(895, 'alice-10', 10, 'He wears his crown on top of a big wig.', false),
(896, 'alice-10', 11, 'He does not look happy in it.', false),
(897, 'alice-10', 12, 'Twelve animals sit in a box at the side.', true),
(898, 'alice-10', 13, '“That is the jury,” Alice thinks.', false),
(899, 'alice-10', 14, 'They all write their names on little boards.', false),
(900, 'alice-10', 15, 'Bill the Lizard is one of them.', false),
(901, 'alice-10', 16, 'His pencil makes a terrible noise.', false),
(902, 'alice-10', 17, 'So Alice takes it away from him.', false),
(903, 'alice-10', 18, 'Now poor Bill writes with his finger!', false),
(904, 'alice-10', 19, 'The White Rabbit stands up with a long paper.', true),
(905, 'alice-10', 20, 'He reads the paper.', false),
(906, 'alice-10', 21, '“The Queen of Hearts, she makes some tarts, all on a summer day.”', false),
(907, 'alice-10', 22, '“The Knave of Hearts, he steals those tarts, and takes them all away!”', false),
(908, 'alice-10', 23, '“Now, jury, what do you think?” says the King.', false),
(909, 'alice-10', 24, '“Not yet! Not yet!” says the Rabbit.', false),
(910, 'alice-10', 25, '“First, we need the witnesses.”', false),
(911, 'alice-10', 26, 'The first witness is the Hatter.', true),
(912, 'alice-10', 27, 'He comes in with a cup of tea and some bread and butter.', false),
(913, 'alice-10', 28, '“Sorry, Your Majesty. I am having my tea,” he says.', false),
(914, 'alice-10', 29, '“Take off your hat!” says the King.', false),
(915, 'alice-10', 30, '“It is not my hat,” says the Hatter.', false),
(916, 'alice-10', 31, '“Then you steal hats!” says the King.', false),
(917, 'alice-10', 32, '“No! I sell hats. I''m a hatter!”', false),
(918, 'alice-10', 33, 'The Queen looks at the Hatter, and he is very nervous.', false),
(919, 'alice-10', 34, 'He eats a piece of his cup, not his bread and butter!', false),
(920, 'alice-10', 35, 'Just then, Alice has a strange feeling.', true),
(921, 'alice-10', 36, 'She is growing again!', false),
(922, 'alice-10', 37, '“Don''t push me!” says the Dormouse next to her.', false),
(923, 'alice-10', 38, '“I can''t help it. I''m growing,” says Alice.', false),
(924, 'alice-10', 39, 'The Hatter is so afraid that his shoes fall off.', false),
(925, 'alice-10', 40, '“You can go,” says the King, and the Hatter runs out.', false),
(926, 'alice-10', 41, '“And off with his head outside!” says the Queen.', false),
(927, 'alice-10', 42, 'But the Hatter is already gone.', false),
(928, 'alice-10', 43, 'Then the White Rabbit reads the next name.', false),
(929, 'alice-10', 44, 'It is “Alice!”', false),
(930, 'alice-11', 1, '“Here!” says Alice, and she jumps up.', true),
(931, 'alice-11', 2, 'But she is very big now.', false),
(932, 'alice-11', 3, 'Her skirt hits the jury box.', false),
(933, 'alice-11', 4, 'All the animals fall out on the floor.', false),
(934, 'alice-11', 5, '“Oh, I''m so sorry!” she says.', false),
(935, 'alice-11', 6, 'She quickly puts them back in the box.', false),
(936, 'alice-11', 7, 'But poor Bill is upside down!', false),
(937, 'alice-11', 8, '“What do you know about the tarts?” the King asks Alice.', true),
(938, 'alice-11', 9, '“Nothing,” says Alice.', false),
(939, 'alice-11', 10, '“Nothing at all?” asks the King.', false),
(940, 'alice-11', 11, '“Nothing at all,” says Alice.', false),
(941, 'alice-11', 12, '“That is very important,” the King says to the jury.', false),
(942, 'alice-11', 13, '“No, not important,” says the White Rabbit.', false),
(943, 'alice-11', 14, '“Important, not important…” the King says quietly.', false),
(944, 'alice-11', 15, 'Then the King reads from his book.', true),
(945, 'alice-11', 16, '“Rule Forty-two.”', false),
(946, 'alice-11', 17, '“All people more than a mile high must leave the court.”', false),
(947, 'alice-11', 18, 'Everybody looks at Alice.', false),
(948, 'alice-11', 19, '“I''m not a mile high,” says Alice.', false),
(949, 'alice-11', 20, '“You are,” says the King.', false),
(950, 'alice-11', 21, '“Two miles high!” says the Queen.', false),
(951, 'alice-11', 22, '“That is not a real rule,” says Alice.', false),
(952, 'alice-11', 23, '“It is new!”', false),
(953, 'alice-11', 24, '“It is the oldest rule in the book,” says the King.', false),
(954, 'alice-11', 25, '“Then it must be Rule Number One,” says Alice.', false),
(955, 'alice-11', 26, 'The King''s face goes white, and he closes his book.', false),
(956, 'alice-11', 27, 'Then the White Rabbit finds a letter.', true),
(957, 'alice-11', 28, 'In the letter, there is a silly poem.', false),
(958, 'alice-11', 29, 'There is no name on it.', false),
(959, 'alice-11', 30, '“The Knave does not write his name,” says the King.', false),
(960, 'alice-11', 31, '“So he is a bad man!”', false),
(961, 'alice-11', 32, 'The Rabbit reads the poem.', false),
(962, 'alice-11', 33, 'It has no meaning at all.', false),
(963, 'alice-11', 34, '“This is very important!” says the King.', false),
(964, 'alice-11', 35, '“Now, jury, give us your verdict.”', false);
insert into sentences (id, chapter_id, position, text_en, paragraph) values
(965, 'alice-11', 36, '“No, no!” says the Queen.', true),
(966, 'alice-11', 37, '“Sentence first, verdict afterwards!”', false),
(967, 'alice-11', 38, '“Nonsense!” says Alice loudly.', false),
(968, 'alice-11', 39, '“The verdict comes first, not the sentence!”', false),
(969, 'alice-11', 40, '“Be quiet!” says the Queen.', false),
(970, 'alice-11', 41, 'Her face is red.', false),
(971, 'alice-11', 42, '“I won''t!” says Alice.', false),
(972, 'alice-11', 43, '“Off with her head!” shouts the Queen.', false),
(973, 'alice-11', 44, 'Nobody moves.', false),
(974, 'alice-11', 45, 'Alice is her full size now.', true),
(975, 'alice-11', 46, 'She is not afraid of them.', false),
(976, 'alice-11', 47, '“Who cares about you?” she says.', false),
(977, 'alice-11', 48, '“You''re nothing but a pack of cards!”', false),
(978, 'alice-11', 49, 'Then all the cards fly up into the air.', false),
(979, 'alice-11', 50, 'They come down on her face and arms.', false),
(980, 'alice-11', 51, 'Alice gives a little scream.', false),
(981, 'alice-11', 52, 'She tries to push them away with her hands.', false),
(982, 'alice-12', 1, '“Wake up, Alice!” says a soft voice.', true),
(983, 'alice-12', 2, 'Alice opens her eyes.', false),
(984, 'alice-12', 3, 'She is by the river again.', false),
(985, 'alice-12', 4, 'Her head is on her sister''s lap.', false),
(986, 'alice-12', 5, 'Her sister takes some dry leaves from her face.', false),
(987, 'alice-12', 6, 'They are not cards.', false),
(988, 'alice-12', 7, 'They are only leaves from the trees.', false),
(989, 'alice-12', 8, '“What a long sleep!” says her sister.', false),
(990, 'alice-12', 9, '“Oh, what a strange dream!” says Alice.', true),
(991, 'alice-12', 10, 'She tells her sister everything.', false),
(992, 'alice-12', 11, 'She talks about the White Rabbit and his watch.', false),
(993, 'alice-12', 12, 'She talks about the bottle, the cake and the pool of tears.', false),
(994, 'alice-12', 13, 'She talks about the Caterpillar, the Cheshire Cat and the mad tea-party.', false),
(995, 'alice-12', 14, 'And she talks about the angry Queen and the pack of cards.', false),
(996, 'alice-12', 15, 'Her sister listens and smiles.', true),
(997, 'alice-12', 16, 'She kisses Alice.', false),
(998, 'alice-12', 17, '“It is a wonderful dream, dear,” she says.', false),
(999, 'alice-12', 18, '“But now run home for your tea. It is late.”', false),
(1000, 'alice-12', 19, 'So Alice gets up and runs home.', false),
(1001, 'alice-12', 20, 'She thinks about her wonderful dream all the way.', false),
(1002, 'alice-12', 21, 'Her sister stays by the river.', true),
(1003, 'alice-12', 22, 'She closes her eyes and thinks about Wonderland too.', false),
(1004, 'alice-12', 23, 'She can almost hear the White Rabbit and the little Mouse.', false),
(1005, 'alice-12', 24, 'She can hear the tea cups of the March Hare.', false),
(1006, 'alice-12', 25, 'She can hear the Queen''s voice: “Off with her head!”', false),
(1007, 'alice-12', 26, 'But she knows one thing.', false),
(1008, 'alice-12', 27, 'When she opens her eyes, everything is normal again.', false),
(1009, 'alice-12', 28, 'The noise of the cups is only the bells of the sheep.', false),
(1010, 'alice-12', 29, 'The voice of the Queen is only a farm boy.', false),
(1011, 'alice-12', 30, 'Then she thinks about the future.', true),
(1012, 'alice-12', 31, 'One day, little Alice will be a woman.', false),
(1013, 'alice-12', 32, 'But she will keep the heart of a child.', false),
(1014, 'alice-12', 33, 'Children will sit around her.', false),
(1015, 'alice-12', 34, 'And she will tell them strange stories.', false),
(1016, 'alice-12', 35, 'Maybe she will tell them about her dream of Wonderland.', false),
(1017, 'alice-12', 36, 'And she will remember these happy summer days.', false);

